/**
 * Creates a debounced function that delays invoking `func` until after `wait`
 * milliseconds have elapsed since the last time it was invoked.
 *
 * @template {(...args: any[]) => void} T
 * @param {T} func - The function to debounce.
 * @param {number} wait - Number of milliseconds to delay execution.
 * @returns {T & { cancel: () => void }} A debounced version of `func` with a `cancel` method.
 */
function debounce(func, wait) {
  let timeoutId;

  /**
   * Debounced wrapper function.
   * @param {...any} args - Arguments passed to the original function.
   */
  const debounced = (...args) => {
    clearTimeout(timeoutId);

    timeoutId = setTimeout(() => {
      func(...args);
    }, wait);
  };

  /**
   * Cancels any pending debounced execution.
   */
  debounced.cancel = () => {
    clearTimeout(timeoutId);
  };

  return debounced;
}

// Usage example:
const logSearch = debounce((query) => {
  console.log(`Searching for: ${query}`);
}, 300);

logSearch('hello');
logSearch('world'); // Only "world" will be logged after 300ms.
